let waveStation=localStorage.getItem('soulroom.waveStation')||'user:onyourwave',waveCategories=[],waveStationsLoading=false;
const waveFallbackStations=[{type:'genre',label:'Жанры',stations:[['rock','Рок'],['pop','Поп'],['electronic','Электроника'],['jazz','Джаз'],['classical','Классика'],['rap','Хип-хоп'],['indie','Инди']].map(([tag,name])=>({id:'genre:'+tag,name}))},{type:'mood',label:'Настроение',stations:[['calm','Спокойное'],['energetic','Энергичное'],['sad','Меланхоличное']].map(([tag,name])=>({id:'mood:'+tag,name}))}];
function waveTuning(){const categories=waveCategories.length?waveCategories:waveFallbackStations;return '<div class="wave-tuning"><label>Настроить волну<select id="waveStation" aria-label="Жанр или настроение"><option value="user:onyourwave">Для меня · Моя волна</option>'+categories.filter(c=>c.type!=='personal').map(c=>'<optgroup label="'+esc(c.label)+'">'+c.stations.map(st=>'<option value="'+esc(st.id)+'" '+(st.id===waveStation?'selected':'')+'>'+esc(st.name)+'</option>').join('')+'</optgroup>').join('')+'</select></label><span class="wave-retry">'+(waveStationsLoading?'Загружаем станции…':'Выбор меняет подборку, но не запускает звук')+'</span></div>'}
async function loadWaveStations(){if(!backend||waveStationsLoading||waveCategories.length)return;waveStationsLoading=true;try{const d=await api('wave/stations');waveCategories=(d.categories||[]).filter(c=>Array.isArray(c.stations));}catch{}finally{waveStationsLoading=false;renderWave()}}
function resetWaveStation(station){waveController?.abort();waveGeneration++;waveLoading=false;wavePending=null;waveStation=station;localStorage.setItem('soulroom.waveStation',station);waveItems=[];waveMessage='';waveActive=false;go('wave');loadWaveStations()}
let waveItems=[],waveLoading=false,waveMessage='',waveEngine='',waveActive=false,waveQueue=null,waveGeneration=0,waveController=null,wavePending=null,waveWarmRetries=0;
const waveBatches=new Map();let waveSources;try{waveSources=JSON.parse(localStorage.getItem('soulroom.waveSources'));if(!Array.isArray(waveSources))throw Error();waveSources=waveSources.filter(s=>favoriteSources.includes(s));if(!waveSources.length)throw Error()}catch{waveSources=['yandex','soundcloud']}
function waveScreen(){const label=waveEngine==='yandex'?'Персональная станция Яндекс.Музыки':waveEngine?'Рекомендации по истории и предпочтениям':'Выбери источники и начни слушать';return heading('Моя волна.','Музыка, которая находит тебя.')+`<section class="wave-hero"><div class="wave-copy"><span class="eyebrow">SOULROOM / ПЕРСОНАЛЬНАЯ СТАНЦИЯ</span><h2>Твой ритм.<br><em>Новые открытия.</em></h2><p>${esc(label)}</p><button class="primary" id="listenWave" ${waveLoading&&!waveItems.length?'disabled':''}>${playerIcon('play')}Слушать волну</button></div><div class="wave-art" aria-hidden="true"><div class="wave-orbit outer"></div><div class="wave-orbit middle"></div><div class="wave-orbit inner"></div><div class="wave-core">${soundDrawing()}</div></div></section><div class="wave-toolbar"><div class="source-toggles">${favoriteSources.map(s=>`<label><input type="checkbox" data-wave-source="${s}" ${waveSources.includes(s)?'checked':''}>${serviceNames[s]}</label>`).join('')}</div><div><button class="secondary" id="refreshWave" ${waveLoading?'disabled':''}>Обновить волну</button>${waveLoading?'<button class="secondary" id="cancelWave">Остановить поиск</button>':''}</div></div>${waveTuning()}<p id="waveStatus" role="status">${waveLoading?'Ищем следующую музыку…':esc(waveMessage||'Лайки, прослушивания и пропуски помогают уточнять рекомендации.')}</p><div id="waveTracks">${waveItems.length?waveItems.map(row).join(''):waveLoading?'<div class="wave-wait"><span>◌</span><p>Собираем твою волну.<br>Воспроизведение начнётся после нажатия «Слушать».</p></div>':'<div class="empty"><h2>Начнём с твоего вкуса</h2><p>Подключи аккаунт Яндекса для персональной «Моей волны».<br>SoundCloud и Spotify добавят рекомендации из своих каталогов.</p><button class="secondary" data-page="connections">Открыть подключения</button></div>'}</div>${waveItems.length?'<div id="waveSentinel" aria-hidden="true"></div>':''}<p class="favorite-footnote">Для настоящей персональной «Моей волны» нужен подключённый аккаунт Яндекса. В других каталогах используется движок рекомендаций soulroom. Spotify может отдавать треки без доступного аудио.</p>`}
function renderWave(){if(page==='wave'){$('#crumb').textContent='МОЯ ВОЛНА';$('#view').innerHTML=waveScreen()}}
async function loadWave({fresh=false,append=false}={}){if(fresh)waveWarmRetries=0;if(!backend){waveMessage='Волна доступна в локальном приложении. Подключи источники и обнови страницу.';renderWave();return false}if(waveLoading)return false;waveLoading=true;const version=++waveGeneration;waveController=new AbortController();renderWave();try{const query=new URLSearchParams({limit:'20',station:waveStation,sources:waveSources.join(','),...(fresh?{live:'1'}:{quick:'1'})});const r=await fetch('/api/wave?'+query,{signal:AbortSignal.any([waveController.signal,AbortSignal.timeout(55000)])});const d=await r.json();if(!r.ok)throw Error(d.error?.message||'Источники не ответили.');if(version!==waveGeneration)return false;const items=Array.isArray(d.items)?d.items:[];items.forEach(t=>waveBatches.set(t.id,d.batchId||null));waveItems=[...new Map([...(append?waveItems:[]),...items].map(t=>[t.id,t])).values()];waveEngine=d.engine||'';waveMessage=d.hint||d.message||(items.length?(d.fromCache?'Показана сохранённая волна. Нажми «Обновить» для новой подборки.':'Подборка готова. Слушай, сохраняй и открывай новое.'):'Не удалось подобрать треки. Проверь подключение выбранных сервисов.');if(append&&waveActive&&queue===waveQueue){const unique=new Set(queue.map(t=>t.id));queue.push(...items.filter(t=>t.playable!==false&&!unique.has(t.id)));renderQueue()}if(d.warming&&waveWarmRetries<12){waveWarmRetries++;setTimeout(()=>{if(version===waveGeneration&&page==='wave'&&!waveLoading)loadWave()},2200)}return items.length>0}catch(e){if(version===waveGeneration)waveMessage=e.name==='AbortError'?'Поиск остановлен. Можно попробовать снова.':'Волна не загрузилась. Проверь источники и попробуй обновить.';return false}finally{if(version===waveGeneration){waveLoading=false;renderWave()}}}
const loadWaveCore=loadWave;loadWave=function(options){if(waveLoading&&wavePending)return wavePending;const promise=loadWaveCore(options).finally(()=>{if(wavePending===promise)wavePending=null});wavePending=promise;return promise};
const renderBeforeWave=render;render=function(){renderBeforeWave();if(page==='wave'){renderWave();if(!waveItems.length&&!waveLoading&&backend)loadWave();loadWaveStations()}};
const waveNav=document.createElement('button');waveNav.dataset.page='wave';waveNav.setAttribute('aria-label','Моя волна');waveNav.innerHTML=playerIcon('repeat')+'<span>Моя волна</span>';document.querySelector('.sidebar nav [data-page=home]').after(waveNav);
const findBeforeWave=find;find=function(id){return findBeforeWave(id)||waveItems.find(t=>t.id===id)};
function waveFeedback(type,t=current,position=audio.currentTime){if(!backend||!t||!waveBatches.has(t.id))return;api('wave/feedback',{method:'POST',body:JSON.stringify({type,track:t,trackId:t.id,station:'user:onyourwave',batchId:waveBatches.get(t.id),position:Math.max(0,Number(position)||0)})}).catch(()=>{})}
async function startWave(t){if(!waveItems.length){const ok=await loadWave();if(!ok)return}const available=waveItems.filter(t=>t.playable!==false);if(!available.length){toast('В подборке нет доступного аудио. Подключи Яндекс или SoundCloud.');return}waveActive=true;queue=[...available];waveQueue=queue;await play(t||available[0]);renderQueue()}
document.addEventListener('click',e=>{if(page!=='wave')return;const row=e.target.closest('#waveTracks [data-track]');if(row&&!e.target.closest('[data-like],[data-track-actions],[data-open-track]')){e.stopImmediatePropagation();const t=find(row.dataset.track);if(t?.playable===false){toast('Для этого трека нужна доступная версия в другом каталоге.');return}startWave(t)}},true);
const stepBeforeWave=step;step=async function(dir){if(waveActive&&queue===waveQueue&&current&&waveBatches.has(current.id)){if(dir===1&&!audio.ended)waveFeedback('skip');const i=queue.findIndex(t=>t.id===current.id);if(dir===1&&i>=queue.length-1){const originalQueue=queue,originalTrack=current.id;await (waveLoading?wavePending:loadWave({fresh:true,append:true}));if(queue!==originalQueue||current?.id!==originalTrack)return;if(queue.length<=i+1){toast('Новая подборка пока не готова. Обнови волну.');return}}}return stepBeforeWave(dir)};
audio.addEventListener('play',()=>{if(waveActive&&queue===waveQueue&&waveBatches.has(current?.id)){waveFeedback('started');const i=queue.findIndex(t=>t.id===current.id);if(queue.length-i<=3&&!waveLoading)loadWave({fresh:true,append:true})}});
const endedBeforeWave=audio.onended;audio.onended=function(){if(waveActive&&queue===waveQueue)waveFeedback('finished');return endedBeforeWave?.call(audio)};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='listenWave')startWave();if(b.id==='refreshWave')loadWave({fresh:true});if(b.id==='moreWave')loadWave({fresh:true,append:true});if(b.id==='cancelWave')waveController?.abort();const id=b.dataset.like||(b.id==='like'?current?.id:null);if(id&&waveBatches.has(id))waveFeedback(likes.has(id)?'like':'dislike',find(id),id===current?.id?audio.currentTime:0)});
document.addEventListener('change',e=>{if(!e.target.dataset.waveSource)return;const selected=[...document.querySelectorAll('[data-wave-source]:checked')].map(x=>x.dataset.waveSource);if(!selected.length){e.target.checked=true;toast('Выбери хотя бы один источник.');return}waveController?.abort();waveGeneration++;waveLoading=false;waveSources=selected;localStorage.setItem('soulroom.waveSources',JSON.stringify(selected));waveItems=[];waveMessage='';waveActive=false;loadWave({fresh:true})});
document.addEventListener('backend-ready',()=>{if(page==='wave'&&!waveItems.length){waveMessage='';loadWave()}});


document.addEventListener('change',e=>{if(e.target.id==='waveStation')resetWaveStation(e.target.value)});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-mood],[data-room]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const mood=b.dataset.mood||rooms[Number(b.dataset.room)]?.[0];if(typeof openMoodWave==='function'){openMoodWave(mood);return}await loadWaveStations();const stations=waveCategories.flatMap(c=>c.stations);const patterns=mood==='Тихий вечер'?/спокой|релакс|тихий|calm|chill/i:mood==='В потоке'?/работ|фокус|концентр|focus|электрон/i:/ноч|меланх|night|sad/i;const found=stations.find(st=>patterns.test(st.name));resetWaveStation(found?.id||(mood==='Тихий вечер'?'mood:calm':mood==='В потоке'?'activity:work':'mood:sad'));},true);
